function spriteMarkup(){return projectFrame('Creative tool / 05','Sprite Sheet Studio','Design a tiny character, preview its movement and export a sheet for a game prototype. No drawing package required.',`<div class="sprite-preview-wrap"><canvas class="sprite-preview" width="420" height="260" aria-label="Animated sprite preview"></canvas><div class="sprite-readout" data-sprite-frame>FRAME 01 / 08</div></div><div class="tool-button-row">${action('Play / pause','sprite-play',true)}${action('New character','sprite-random')}${action('Export sprite sheet','sprite-export')}</div><pre class="sprite-css" data-sprite-css>/* Export a sprite sheet to use this loop. */</pre><button type="button" class="tool-button" data-action="sprite-copy-css">Copy animation CSS</button>`,panel('Character design',select('Body','sprite-body',[['orb','Orbit head'],['bot','Service bot'],['moth','Night moth'],['blob','Soft shape'],['mask','Paper mask'],['bird','Small bird']])+select('Movement','sprite-motion',[['walk','Walk cycle'],['hover','Hover'],['bounce','Bounce'],['glitch','Misstep'],['blink','Look around']])+select('Palette','sprite-palette',[['mineral','Mineral'],['signal','Signal'],['bruise','Bruise'],['dusk','Dusk'],['ultraviolet','Ultraviolet'],['toxic','Toxic'],['infrared','Infrared'],['archive','Archive'],['abyss','Abyss'],['candy','Candy glass'],['oxidized','Oxidized'],['lunar','Lunar'],['fever','Fever'],['sediment','Sediment']])+range('Frame count','sprite-frames',4,12,8)+range('Animation speed','sprite-speed',2,18,8,' FPS')+range('Shape detail','sprite-detail',0,100,65)),'The sprite sheet is drawn in Canvas and exported as a transparent PNG. A CSS snippet is provided for a background-position animation.');}

