    function step(now){if(disposed||!playing||!siteMotionEnabled||!animationAllowed){raf=0;return;}const speedControl=$('[data-range="sprite-speed"]',root);if(!speedControl){playing=false;raf=0;return;}if(now-last>1000/(+speedControl.value)){frame=(frame+1)%(+$('[data-range="sprite-frames"]',root).value);last=now;draw();}raf=requestAnimationFrame(step);}function updateCssSnippet(){const speed=+$('[data-range="sprite-speed"]',root).value,frames=+$('[data-range="sprite-frames"]',root).value;frame%=frames;const strip=frames*100;const css=`.sprite { width: 128px; height: 128px; background-image: url("sprite-sheet.png"); background-size: ${strip}% 100%; animation: sprite-loop ${(frames/speed).toFixed(2)}s steps(${frames}) infinite; }\n@keyframes sprite-loop { to { background-position: 100% 0; } }`;$('[data-sprite-css]',root).textContent=css;draw();}function draw(){paint(pctx,preview.width,preview.height,frame);$('[data-sprite-frame]',root).textContent=`FRAME ${String(frame+1).padStart(2,'0')} / ${String(+$('[data-range="sprite-frames"]',root).value).padStart(2,'0')}`;}
