    async function loadFiles(fileList){const token=++loadToken;images=[];draw();const list=[...fileList].filter(f=>/^image\/(png|jpeg|webp|avif)$/i.test(f.type||'')).slice(0,36);const status=$('[data-contact-status]',root);if(!list.length){status.textContent='Choose PNG, JPEG, WebP or AVIF images.';return;}status.textContent=`Preparing 0 / ${list.length} images…`;const results=new Array(list.length);let cursor=0,failed=0,done=0;async function worker(){while(!disposed&&token===loadToken){const index=cursor++;if(index>=list.length)return;try{const result=await decodeLocalImage(list[index],480);if(disposed||token!==loadToken)return;results[index]={img:result.canvas,name:list[index].name};}catch(_){failed++;}done++;status.textContent=`Preparing ${done} / ${list.length} images…`;}}await Promise.all(Array.from({length:Math.min(3,list.length)},()=>worker()));if(disposed||token!==loadToken)return;images=results.filter(Boolean);$('[data-contact-list]',root).innerHTML=images.map((it,i)=>`<span>${String(i+1).padStart(2,'0')} · ${esc(it.name)}</span>`).join('');status.textContent=`${images.length} images ready · ${failed} skipped · previews optimized to 480 px.`;draw();if(fileList.length>36)toast(null,'The sheet is limited to the first 36 images.');}
    fileInput.addEventListener('change',/** @param {CurioidDOMEvent} e */ e=>{const files=Array.from(e.target.files||[]);fileInput.value='';if(files.length)loadFiles(files);});drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag-over');});drop.addEventListener('dragleave',()=>drop.classList.remove('drag-over'));drop.addEventListener('drop',/** @param {CurioidDOMEvent} e */ e=>{e.preventDefault();drop.classList.remove('drag-over');if(e.dataTransfer?.files?.length)loadFiles(e.dataTransfer.files);});
