    file.addEventListener('change',/** @param {CurioidDOMEvent} e */ async e=>{const f=e.target.files?.[0];file.value='';if(!f)return;const token=++loadToken;try{$('[data-pixel-status]',root).textContent='Preparing local image…';const result=await decodeLocalImage(f,720);if(disposed||token!==loadToken)return;load(result.canvas);}catch(error){if(!disposed&&token===loadToken)toast(null,error.message||'Could not open that image.');}});
